package cn.xinji.agentplatform.adjudication.casework;
import cn.xinji.agentplatform.adjudication.materials.MaterialCandidateDecisions.*;
import cn.xinji.agentplatform.adjudication.materials.MaterialOrganizationModel.*;
import cn.xinji.agentplatform.adjudication.casework.CaseWorkContract.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.transaction.support.TransactionTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.xinji.agentplatform.adjudication.casework.AdjudicationCaseWork.sha256;
/** H2 DAO C only. Not DM8, no actual person adopting, no provider call. */
class MaterialDecisionStoreTest {
    @TempDir Path keys;JdbcTemplate db;TransactionTemplate tx;JdbcMaterialDecisionStore store;CaseWorkCodec codec;
    Instant now=Instant.parse("2026-10-05T00:00:00Z");Clock clock=Clock.fixed(now,ZoneOffset.UTC);String run=UUID.randomUUID().toString();
    @BeforeEach void setup()throws Exception{var ds=new DriverManagerDataSource("jdbc:h2:mem:adj-decision-"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));codec=new CaseWorkCodec(new ObjectMapper().registerModule(new JavaTimeModule()));try(var c=ds.getConnection()){for(var f:List.of("V086__adjudication_case_work.sql","V093__adjudication_material_decisions.sql"))ScriptUtils.executeSqlScript(c,new FileSystemResource("db/dm8/"+f));}db.update("INSERT INTO adj2_case_work VALUES('case1','org','scope',1,NULL)");store=new JdbcMaterialDecisionStore(db,new MaterialDecisionVault(keys,clock),codec,clock);}
    Decision decision(String base,long org){return new Decision(UUID.randomUUID().toString(),base,"case1",run,"c1",org+1,org,1,org==1?Action.ACCEPT:Action.EDIT,Semantic.HUMAN_REVIEWED_MATERIAL_STATEMENT,Kind.PARTY_ASSERTION,cn.xinji.agentplatform.adjudication.materials.MaterialOrganizationModel.Side.APPLICANT,"机器陈述","人工整理😀","不能认定事实",new Source("s","v1","段落一",sha256("原文"),InputKind.PROJECT_AUTHORED),"原文",0,2,"s1",Scope.SELECTED_MATERIALS,"actor",now,now.plus(Duration.ofDays(2)));}
    void save(Decision d,String key){tx.executeWithoutResult(s->{store.lockHead("case1");store.save(d,"identity",key,sha256(key),sha256("policy"),sha256("input"));});}
    @Test void uuidKeyCollisionCannotDeletePriorKey(){var d=decision(null,1);save(d,"one");assertThrows(RuntimeException.class,()->save(d,"collision"));assertTrue(Files.exists(keys.resolve(d.versionId()+".key")));assertEquals(d,store.load("case1",d.versionId()));}
    @Test void pendingKeyCollisionCannotDeleteExistingFile()throws Exception{String id=UUID.randomUUID().toString();var pending=keys.resolve(id+".pending");Files.writeString(pending,"owned-by-another-inflight-operation");var vault=new MaterialDecisionVault(keys.resolve("other"),clock);Files.writeString(keys.resolve("other").resolve(id+".pending"),"existing");assertThrows(IllegalStateException.class,()->vault.seal(id,now.plusSeconds(60),"aad","payload"));assertEquals("existing",Files.readString(keys.resolve("other").resolve(id+".pending")));}
    @Test void sameJdbcUrlButDifferentDataSourceCannotEscapePrimaryTransaction(){var ds=new DriverManagerDataSource(((DriverManagerDataSource)db.getDataSource()).getUrl(),"sa","");var wrong=new JdbcMaterialDecisionStore(new JdbcTemplate(ds),new MaterialDecisionVault(keys.resolve("wrong"),clock),codec,clock);assertThrows(IllegalStateException.class,()->tx.executeWithoutResult(t->wrong.lockHead("case1")));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM adj3_material_decision_head",Integer.class));}
    @Test void requiresActualTransaction(){assertThrows(IllegalStateException.class,()->store.save(decision(null,1),"identity","k",sha256("k"),sha256("policy"),sha256("input")));}
    @Test void newVaultAndDaoReloadExactVersionAndCipherDoesNotContainText(){var d=decision(null,1);save(d,"one");var reloaded=new JdbcMaterialDecisionStore(db,new MaterialDecisionVault(keys,clock),codec,clock);assertEquals(d,reloaded.load("case1",d.versionId()));assertEquals(d.versionId(),reloaded.requestVersion("case1","identity","one",sha256("one")));assertFalse(db.queryForObject("SELECT payload FROM adj3_material_decision_version",String.class).contains("人工"));assertThrows(IllegalArgumentException.class,()->reloaded.load("other",d.versionId()));}
    @Test void ciphertextTamperCannotBeRepairedByChangingSha(){var d=decision(null,1);save(d,"one");db.update("UPDATE adj3_material_decision_version SET payload=?,payload_sha=?","a.b",sha256("a.b"));assertThrows(IllegalStateException.class,()->store.load("case1",d.versionId()));}
    @Test void expiryRefusesReadAndDeletesOnlyNewDerivedChainKeys(){var d=decision(null,1);save(d,"one");var n=decision(d.versionId(),2);save(n,"two");var later=Clock.fixed(now.plus(Duration.ofDays(3)),ZoneOffset.UTC);var expired=new JdbcMaterialDecisionStore(db,new MaterialDecisionVault(keys,later),codec,later);assertThrows(SecurityException.class,()->expired.load("case1",d.versionId()));expired.purgeExpired(tx);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM adj3_material_decision_version",Integer.class));assertEquals(2,expired.head("case1"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM adj2_case_work",Integer.class));assertFalse(Files.exists(keys.resolve(d.versionId()+".key")));assertFalse(Files.exists(keys.resolve(n.versionId()+".key")));}
    @Test void missingBaseAndMissingCaseFkFailWithoutLeavingKey(){var d=decision(UUID.randomUUID().toString(),1);assertThrows(RuntimeException.class,()->save(d,"orphan"));assertEquals(0,store.head("case1"));assertFalse(Files.exists(keys.resolve(d.versionId()+".key")));}
    @Test void cannotForkBaseChainAndDoesNotAdvanceCounter(){var d=decision(null,1);save(d,"one");var n=decision(d.versionId(),2);save(n,"two");var fork=decision(d.versionId(),3);assertThrows(RuntimeException.class,()->save(fork,"fork"));assertEquals(2,store.head("case1"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM adj3_material_decision_version",Integer.class));}
    @Test void nonemptyReverseRefusesBeforeAnyDrop()throws Exception{save(decision(null,1),"one");assertThrows(Exception.class,()->{try(var c=db.getDataSource().getConnection()){ScriptUtils.executeSqlScript(c,new FileSystemResource("db/dm8/U093__adjudication_material_decisions.sql"));}});assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM adj3_material_decision_version",Integer.class));assertEquals(1,store.head("case1"));}
    @Test void emptyReverseActuallyDropsOnlyNewTables()throws Exception{try(var c=db.getDataSource().getConnection()){ScriptUtils.executeSqlScript(c,new FileSystemResource("db/dm8/U093__adjudication_material_decisions.sql"));}assertThrows(RuntimeException.class,()->db.queryForObject("SELECT COUNT(*) FROM adj3_material_decision_version",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM adj2_case_work",Integer.class));}
    @Test void purgedPayloadDoesNotPermitDestructiveHeadReverse()throws Exception{var d=decision(null,1);save(d,"one");var later=Clock.fixed(now.plus(Duration.ofDays(3)),ZoneOffset.UTC);new JdbcMaterialDecisionStore(db,new MaterialDecisionVault(keys,later),codec,later).purgeExpired(tx);assertThrows(Exception.class,()->{try(var c=db.getDataSource().getConnection()){ScriptUtils.executeSqlScript(c,new FileSystemResource("db/dm8/U093__adjudication_material_decisions.sql"));}});assertEquals(1,store.head("case1"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_NAME='CK_ADJ3_DEC_REVERSE_EMPTY'",Integer.class),"Refusal must not brick the empty payload table after expiry cleanup");}
}
